    asked = []

    def answer_dialog(tries=[0]):
        dlg = QtWidgets.QApplication.activeModalWidget()
        if dlg is None:                            # (not open yet: a slower run — look again)
            tries[0] += 1
            if tries[0] < 50:
                QtCore.QTimer.singleShot(100, answer_dialog)
