def stair_ready_flow():
    """0.435 (the addon's «Gerar escada»: a stair ready to put down): the Stair tool, «Colocar ▸ Pronta», an L — its
    turn and its point on the bar; R turns it to 180°, Space holds it by the outer corner of its first step; under the
    mouse at (4, 2) the whole stair shown; one click: an L there, going to −x, the middle of its first step half its
    width from the point clicked, on the side away from its turn."""
    from arqbim.model import bim as bim_actions
    key(Qt.Key.Key_N, Qt.KeyboardModifier.ControlModifier)
    pump(400)
    bim_actions.add_storey(doc, "Piso 1", 3.0)
    win.set_active_storey(doc.ifc.storeys()[0][0])
    win.open_view("3d", None)
    pump(200)
    vp.set_view("top", center=(3.0, 2.0, 0.0), radius=6.0)
    pump(300)
    win.tool_actions["stair"].trigger()
    pump(100)
    win._context_option("placing", "ready")
    win._context_option("form", "l")
    pump(60)
    bar = [o.key for o in win.tool.options()]
    on_bar = "angle" in bar and "anchor" in bar
    move(near((4.0, 2.0, 0.0)), 4)
    pump(60)
    key(Qt.Key.Key_R)
    key(Qt.Key.Key_Space)
    move(near((4.05, 2.0, 0.0)), 2)
    move(near((4.0, 2.0, 0.0)), 2)
    pump(100)
    turned = win.tool.angle == 180 and win.tool.anchor == "outside"
    preview = vp._lines.visible
    click()
    pump(400)
    stairs = doc.ifc.file.by_type("IfcStair")
    placed = False
    where = None
    if len(stairs) == 1:
        m = doc.ifc._placement_si(stairs[0])
        where = (np.round(m[:3, 3], 2).tolist(), np.round(m[:3, 0], 3).tolist())
        # going to −x, turning left (its left: −y): the outer corner is on its right (+y) — the middle 0,50 m in −y
        placed = stairs[0].PredefinedType == "QUARTER_TURN_STAIR" and np.allclose(m[:3, 0], (-1.0, 0.0, 0.0),
                                                                                    atol=1e-6) \
            and abs(m[0, 3] - 4.0) < 0.06 and abs(m[1, 3] - 1.5) < 0.06
    win._context_option("placing", "two")                   # (the tool as the other flows expect it)
    key(Qt.Key.Key_Escape)
    win.set_tool("select")
    vp.set_view("iso")
    vp.zoom_extents()
    pump(300)
    shot("435_escada_pronta.png")
    check("escada_pronta", on_bar and turned and preview and placed,
          "barra={} rodada={} previa={} posta={} {}".format(on_bar, turned, preview, placed, where))


def curtain_shapes_flow():
    """0.436 (the addon's «Fachada de vidro» circular and «por face»): a 6 × 4 × 9 m volume; the Curtain wall tool,
    «Forma ▸ Por face», a click on its front face: a curtain wall 6 m long and 9 m high just in front of it; «Forma ▸
    Arco», three clicks — (8, 8), (12, 8) and (10, 9) —: one along that arc (radius 2,5 m), free of any wall."""
    from arqbim.core import sketch_geometry as sg
    from arqbim.model.document import AddObject, SketchObject
    key(Qt.Key.Key_N, Qt.KeyboardModifier.ControlModifier)
    pump(400)
    m = sg.rectangle_matrix(np.array((0.0, 0.0, 0.0)), np.array((1.0, 0.0, 0.0)), np.array((0.0, 1.0, 0.0)))
    mesh = sg.rectangle_mesh(6.0, 4.0)
    sg.push_pull(mesh, 0, m, 9.0)
    doc.execute(AddObject(SketchObject("Volume", m, mesh)))
    win.views.open(("3d",))
    vp.set_view("front")
    vp.zoom_extents()
    pump(500)
    win.tool_actions["curtain_wall"].trigger()
    pump(200)
    win._context_option("shape", "face")
    pump(100)
    move(near((3.0, -0.001, 4.5)), 3)
    pump(150)
    shown = win.tool._face is not None
    click()
    pump(600)
    walls = [e.GlobalId for e in doc.ifc.file.by_type("IfcCurtainWall")]
    by_face = None
    if len(walls) == 1:
        p = doc.ifc.curtain_params(walls[0])
        by_face = (round(p["length"], 3), round(p["height"], 3), round(float(p["start"][1]), 3))
    face_ok = by_face == (6.0, 9.0, -0.075)
    win._context_option("shape", "arc")
    vp.set_view("top", center=(10.0, 7.0, 0.0), radius=8.0)
    pump(400)
    for q in ((8.0, 8.0, 0.0), (12.0, 8.0, 0.0), (10.0, 9.0, 0.0)):
        move(near(q), 3)
        pump(80)
        click()
        pump(150)
    pump(500)
    arc = [e.GlobalId for e in doc.ifc.file.by_type("IfcCurtainWall") if e.GlobalId not in walls]
    radius = round(doc.ifc.curtain_params(arc[0])["radius"] or 0.0, 2) if len(arc) == 1 else None
    arc_ok = radius is not None and abs(radius - 2.5) < 0.08 and doc.ifc.host_wall(arc[0]) is None
    win._context_option("shape", "line")
    key(Qt.Key.Key_Escape)
    win.set_tool("select")
    vp.set_view("iso")
    vp.zoom_extents()
    pump(300)
    shot("436_fachada_arco_face.png")
    check("fachada_arco_e_face", shown and face_ok and arc_ok,
          "mostrada={} face={} arco_raio={}".format(shown, by_face, radius))


