    pump(100)
    for p in ((0.0, -1.0, 0.0), (4.0, -1.0, 0.0), (4.0, 2.0, 0.0)):
        move(near(p), 4)
        pump(60)
        click()
    key(Qt.Key.Key_Return)
    pump(300)
    path_ok = len(doc.ifc.file.by_type("IfcRailing")) == 1
    win._context_option("shape", "stair")
