    move(near((5.0, 7.7, vp.cut_level())), 4)
    pump(100)
    click()
    pump(150)
    click()
    pump(600)
    opened = vp.section is not None and "N" == (vp.section_view or ("", ""))[1]
    paper = drawings.plan(doc, ground, "Planta")
