    in_plan = len(vp._cloud_objects) == 1
    shot("156_nuvem_planta.png")

    def bigger():
        d = getattr(win, "_cloud_dialog", None)
        if d is None or not d.isVisible():
            QtCore.QTimer.singleShot(100, bigger)
