        seen["floor"], seen["height"] = round(d.floor.value(), 2), round(d.height.value(), 2)
        seen["walls"] = sorted(round(th, 2) for _a, _b, th in d.axes)
        seen["openings"] = [k for _i, k in d.openings]                 # (0.213: the door's gap, a door)
